import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import { AuthProvider } from "./contexts/AuthContext"; // Ensure this path is correct
import PrivateRoute from "./components/PrivateRoute"; // Ensure this path is correct
import Login from "./components/Login"; // Ensure this path is correct
import SignUp from "./components/SignUp"; // Ensure this path is correct
import MerchantDashboard from "./components/MerchantDashboard"; // Ensure this path is correct
import AdminDashboard from "./components/AdminDashboard"; // Ensure this path is correct

function App() {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/sign-up" element={<SignUp />} />
          <Route
            path="/merchant-dashboard"
            element={
              <PrivateRoute role="M">
                <MerchantDashboard />
              </PrivateRoute>
            }
          />
          <Route
            path="/admin-dashboard"
            element={
              <PrivateRoute role="SA">
                <AdminDashboard />
              </PrivateRoute>
            }
          />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

export default App;
